/bin/bash -lc 'RUN=<HOME> find "$RUN/drafts" -type f -maxdepth 3 -printf '"'%p %s bytes\\n' | sort; printf '%s\\n' '--- nonpass citations in draft tex ---'; .venv/bin/python - <<'PY'
import json,re,glob,os
run='<HOME>'; aud=json.load(open(run+'/state/CITATION_AUDIT.json')); non=[r['key'] for r in aud['per_entry'] if r['verdict']"'!='"'PASS']
files=glob.glob(run+'/drafts/**/*.tex',recursive=True)
print('tex files',files)
for k in non:
 hits=[]
 for f in files:
  t=open(f,encoding='utf8').read()
  if k in t: hits.append(os.path.basename(f))
 print(k, '=>', ','.join(hits) if hits else '-')
PY
printf '%s\\n' '--- draft keys stats ---'; .venv/bin/python - <<'PY'
import glob,re,collections,os
run='<HOME>';
for f in glob.glob(run+'/drafts/**/*.tex',recursive=True):
 t=open(f,encoding='utf8').read(); ks=[]
 for m in re.finditer(r'\\\\cite[a-zA-Z*]*\\s*(?:\\[["'^]]*'"\\])?\\{(["'^}]*)'"\\}',t): ks.extend([x.strip() for x in m.group(1).split(',')])
 print(os.path.basename(f),len(ks),len(set(ks)), 'sample',ks[:10])
PY"

